userscript.function:

if(!formObj.validate()){
    return
}

var resultData = null;
if(templateData){
    var convert52digits = function(i){
        var x52 = function(n){
            if(n > 25){
                n += 6;
            }
            return String.fromCharCode(65+n);
        }

        var a = i % 52
        var b = (i - a) / 52
        if(b > 51){
            return x52(a) + convert52digits(b);
        }else{
            return x52(a);
        }
    }

    templateData = templateData.replaceAll("%REPLACEID%", convert52digits(new Date().getTime()));
    templateData = templateData.replaceAll("%PREFIX%", formObj.getValue("PREFIX"));
    templateData = templateData.replaceAll("%PATH_1%", formObj.getValue("PATH_1"));
    templateData = templateData.replaceAll("%PATH_2%", formObj.getValue("PATH_2"));
    for(var i in templateCodes){
        templateData = templateData.replaceAll("%CODE_"+templateCodes[i]+"%", formObj.getValue("CODE_"+templateCodes[i]));
    }

    resultData = JSON.parse(templateData)
    var project = formObj.getValue('PROJECT');
    for(var i in resultData){
        resultData[i].info.PROJECT = project
    }
}else{
    resultData = [{info:formObj.getFormData()}]
}

var ro = Sepoa.params.callback.apply( Sepoa.params.callObj,[resultData]);
if(ro.status){
    selfObj.close();
}else{
    Alert(ro.message);
}


var resultData = null;
if(templateData){
    var convert52digits = function(i){
        var x52 = function(n){
            if(n > 25){
                n += 6;
            }
            return String.fromCharCode(65+n);
        }

        var a = i % 52
        var b = (i - a) / 52
        if(b > 51){
            return x52(a) + convert52digits(b);
        }else{
            return x52(a);
        }
    }

    resultData = JSON.parse(templateData)
    var project = formObj.getValue('PROJECT');
    for(var i in resultData){
        resultData[i].info.PROJECT = project
    }
}else{
    resultData = [{info:formObj.getFormData()}]
}

var ro = Sepoa.params.callback.apply( Sepoa.params.callObj,[resultData,"TEMPLATE"]);

if(ro.status){
    selfObj.close();
}else{
    Alert(ro.message);
}


        	var data = item.data;
        	var id = item.name;
        	templateData = data;
            templateCodes = [];
            if(formObj && formObj.unload){
                formObj.unload();
            }
            var formOptions = null;
            changeMode(id);
            if(id == 'NEW'){
                formOptions = [
                	{type: "block", width: "auto", blockOffset: "0", offsetLeft: 45, offsetTop: 5, list: [
						{type: "select", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PROJECT'), name: "PROJECT", options:Sepoa.params.formModuleOption},
						{type: "select", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_DIR_NONSTD'), name: "NONSTD_PATH", options:[
							{text:"", value:""},
							{text:"Y", value:"Y"}
						]},
						{type: "input", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PATH_1'), name: "PATH_1"},
						{type: "input", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PATH_2'), name: "PATH_2"},
						{type: "input", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PATH_3'), name: "PATH_3", disabled:true},
						{type: "input", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_NAME'), name: "NAME"},
						{type: "input", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PATH'), name: "PATH", offsetTop:"8", disabled: true}
                	]},
                	{type: "container", width: "auto", className: "AREA_DIVISION", blockOffset: "0", name: "AREA_DIVISION", offsetTop: 20},
                	{type: "block", width: "auto", blockOffset: "0", offsetLeft: 45, offsetTop: 5, list: [
						{type: "input", width:"140", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PREFIX'), name: "PREFIX", required:true},
						{type: "newcolumn"},
						{type: "input", width:"140", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_CODE'), name: "CODE", required:true}
                	]}
                ]
            }else{
                var p = JSON.parse(data);
                for(const m of data.matchAll(/%CODE_([0-9]{0,})%/g)){
                    if(templateCodes.indexOf(m[1]) < 0){
                        templateCodes.push(m[1]);
                    }
                }
                var formCodeList = [];
                for(var i in templateCodes){
                    var n = p["%PREFIX%_%CODE_"+templateCodes[i]+"%"].info.NAME;
                    if(formCodeList.length == 0){
                        formCodeList.push(
                        {type: "block", width: "auto", blockOffset: "0", list: [
                            {type: "input", width:"140", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PREFIX'), name: "PREFIX", required:true, className:"rightAlign"},
                            {type: "newcolumn"},
                            {type: "label", labelWidth:"7", label:"_", className: "none_label_top"},
                            {type: "newcolumn"},
                            {type: "input", width:"140", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_CODE') + " ( "+n+" )", name: "CODE_"+templateCodes[i], required:true}
                        ]}
                        )

                    }else{
                        formCodeList.push(
                        {type: "block", width: "auto", blockOffset: "0", offsetTop: 5, list: [
                            {type: "label", labelWidth:"152", label:"", name: "PREFIX_"+templateCodes[i], className: "none_label_top rightAlign"},
                            {type: "newcolumn"},
                            {type: "input", width:"140",label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_CODE') + " ( "+n+" )", name: "CODE_"+templateCodes[i], required:true}
                        ]}
                        )
                    }
                }
                formOptions = [
					{type: "block", width: "auto", blockOffset: "0", offsetLeft: 45, offsetTop: 5, list: [
						{type: "select", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PROJECT'), name: "PROJECT", options:Sepoa.params.formModuleOption},
						{type: "input", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PATH_1'), name: "PATH_1"},
						{type: "input", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PATH_2'), name: "PATH_2"},
						{type: "input", width:"300", value: "", label:Sepoa.cache.text.get('SCREEN_BUILDER.INFO_FORM_PATH_3'), name: "PATH_3", disabled:true}
					]},
					{type: "container", width: "auto", className: "AREA_DIVISION", blockOffset: "0", name: "AREA_DIVISION", offsetTop: 20},
					{type: "block", width: "auto", blockOffset: "0", offsetLeft: 45, offsetTop: 5, list: formCodeList}
                ]
            }
            if(formOptions != null){
                formObj = $sObject.formObj = new SepoaMultiDhtmlXFormObject(formBox, 'formObj', [formOptions]);
                formObj.attachEvent("onChange", onChange)
                if(id != "NEW"){
                    formObj.attachEvent("onBeforeChange", onBeforeChange)
                    formObj.attachEvent("onChange", onChange2)
                }
            }
            if(Sepoa.params.ext){
            	formObj.setData(Sepoa.params.ext, "json");
            	formObj.callEvent("onChange", ["PREFIX", Sepoa.params.ext.PREFIX])
            	if(id != 'NEW'){
            		formObj.setValue("CODE_1", Sepoa.params.ext.CODE);
            	}
            }


if(name == "PREFIX"){
    this.setItemValue('PREFIX', nValue.toUpperCase())
    return false;
}
return true;


switch(id){
case "cancel":
    doCancel();
    break;
case "save":
    doSave();
    break;
case "update":
    doUpdate();
    break;
default:
    break;
}


if(name == "NONSTD_PATH"){
    if(value == 'Y'){
        this.enableItem('PATH_3');
        this.hideItem('PATH_2')
        this.setItemWidth('PATH_1', '274')
        this.setItemValue('PATH_2', '', true)
        this.setItemValue('PATH_3', '')
    }else{
        this.setItemWidth('PATH_1', '129')
        this.disableItem('PATH_3');
        this.showItem('PATH_2')
        this.setItemValue('PATH_1', '', true)
        this.setItemValue('PATH_2', '')
    }
}else if(["PATH_1","PATH_2", "PATH_3", "NAME"].indexOf(name) + 1){
    var PATH_1 = formObj.getValue("PATH_1").trim();
    var PATH_2 = formObj.getValue("PATH_2").trim();
    var PATH_3 = formObj.getValue("PATH_3").trim();
    var NAME = formObj.getValue("NAME").trim();
    var NONSTD_PATH = formObj.getValue('NONSTD_PATH').trim();

    var pathArray = [];
    if(PATH_1 && PATH_2 && name != "PATH_3"){
        PATH_3 = PATH_1+""+PATH_2;
        formObj.setValue("PATH_3", PATH_3)

        if(NAME){
            pathArray.push(PATH_1, PATH_2, PATH_3+NAME);
        }
    }else if(PATH_1 && NONSTD_PATH == 'Y' && (PATH_3+NAME)){
        pathArray.push(PATH_1, PATH_3+NAME);
    }

    if(NAME){
        formObj.setValue("PATH", "/"+pathArray.join("/")+".xml", true);
    }
}


if(name.indexOf("PREFIX") == "0"){
    formObj.forEachItem(function(obj, id){
        if(id.indexOf("PREFIX") == "0" && obj.getItemType(id) == "label"){
            obj.setItemLabel(id, value+"_");
        }
    })
}


            var ro = Sepoa.params.callback.apply( Sepoa.params.callObj,[
